# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps


def make(*texts):
    return [parse_span(text) for text in texts]


class FindGapsTests(unittest.TestCase):
    OPEN = parse_span("09:00-17:00")

    def test_gap_in_the_middle(self):
        work = make("09:00-12:00", "13:00-17:00")
        result = find_gaps(work, self.OPEN)
        self.assertEqual(
            result, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        result = find_gaps(make("10:00-16:00"), self.OPEN)
        self.assertEqual(
            result,
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)",
            ],
        )

    def test_nobody_worked(self):
        result = find_gaps([], self.OPEN)
        self.assertEqual(
            result, ["gap 09:00-17:00 (480 min)"]
        )

    def test_full_coverage_no_gaps(self):
        work = make("09:00-13:00", "13:00-17:00")
        result = find_gaps(work, self.OPEN)
        self.assertEqual(result, [])

    def test_overlap_and_order_ignored(self):
        work = make("14:00-17:00", "09:00-12:30")
        work += make("12:00-13:00")
        result = find_gaps(work, self.OPEN)
        self.assertEqual(
            result, ["gap 13:00-14:00 (60 min)"]
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(make("08:00-12:00"), self.OPEN)

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            find_gaps(make("16:00-18:00"), self.OPEN)
